'<rect x="7" y="4" width="24" height="31" rx="4" fill="#e7dec9"/><text x="19" y="27" text-anchor="middle" fill="#47665a" font-family="Georgia" font-size="25">?</text><circle cx="28" cy="27" r="7" stroke="#b29159" stroke-width="3" fill="none"/><path d="M32 33L37 38" stroke="#b29159" stroke-width="4"/>',lastcard:'<rect x="4" y="7" width="22" height="29" rx="4" fill="#a94252" stroke="#f5ecd4"/><rect x="15" y="3" width="22" height="29" rx="4" fill="#315f93" stroke="#f5ecd4"/><text x="26" y="23" text-anchor="middle" fill="#fff9e9" font-size="18">7</text>',wordscale:'<path d="M3 8Q3 3 9 3H23Q29 3 29 9V18Q29 23 23 23H13L7 29V23Q3 23 3 18Z" fill="#e5e6ce"/><path d="M16 18Q16 13 22 13H31Q37 13 37 19V27Q37 32 31 32V37L25 32H22Q16 32 16 27Z" fill="#bfa78e"/>',
  reversi:'<circle cx="15" cy="16" r="11" fill="#314c3e" stroke="#70846e"/><path d="M8 12Q13 6 20 10" fill="none" stroke="#90a18a" stroke-width="1.5" opacity=".5"/><circle cx="25" cy="25" r="11" fill="#efefdf" stroke="#b3bba5"/>',
  yacht:'<rect x="6" y="5" width="28" height="30" rx="6" fill="#f2efdf" stroke="#b5bda7" stroke-width="1.5"/><g fill="#36584b"><circle cx="14" cy="13" r="2.5"/><circle cx="26" cy="13" r="2.5"/><circle cx="20" cy="20" r="2.5"/><circle cx="14" cy="27" r="2.5"/><circle cx="26" cy="27" r="2.5"/></g>',
  blackjack:'<rect x="5" y="4" width="25" height="31" rx="4" fill="#f5efdc" stroke="#c1b38c" stroke-width="1.5"/><text x="10" y="20" fill="#36584b" font-family="Georgia,serif" font-size="16">A</text><circle cx="28" cy="29" r="10" fill="#cfad69" stroke="#937640"/><text x="28" y="33" text-anchor="middle" fill="#433b28" font-family="Georgia,serif" font-size="12">21</text>',
  hitblow:'<circle cx="11" cy="11" r="7.5" fill="#b85869"/><circle cx="29" cy="11" r="7.5" fill="#4c7fa6"/><circle cx="11" cy="29" r="7.5" fill="#5a896e"/><circle cx="29" cy="29" r="7.5" fill="#d9b75d"/><circle cx="11" cy="11" r="3" fill="#fff8e8"/><path d="M29 6L34 11L29 16L24 11Z" fill="#fff8e8"/><path d="M11 24L16 33H6Z" fill="#fff8e8"/><path d="M29 23L30.5 27H35L31.5 29.5L33 34L29 31.5L25 34L26.5 29.5L23 27H27.5Z" fill="#524b31"/>',
  texas:'<rect x="5" y="7" width="18" height="26" rx="3" fill="#3c6268" stroke="#e8e2cb" stroke-width="1.6" transform="rotate(-10 14 20)"/><rect x="18" y="5" width="17" height="27" rx="3" fill="#55757c" stroke="#eee8d3" stroke-width="1.6" transform="rotate(9 26 19)"/><path d="M27 11L32 18L27 25L22 18Z" fill="none" stroke="#bfc8b5" stroke-width="1.2"/><circle cx="12" cy="30" r="8" fill="#b58d50" stroke="#f3dfad" stroke-width="2" stroke-dasharray="3 2"/><circle cx="12" cy="30" r="4" fill="none" stroke="#f3dfad"/>',
