function playSound(soundSettings=settings){if(!soundSettings.sound||Number(soundSettings.volume??.45)<=0)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(460,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(180,ctx.currentTime+.07);g.gain.setValueAtTime(Number(soundSettings.volume??.45)*.2,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.1);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.1);o.onended=()=>ctx.close();}catch{}}
