 if(id==='lateral'){const solved=done.filter(g=>g.result==='clear').length;return {summary:done.length+'問 · '+solved+'問解明'+tail,items:[[done.length,'遊び終えた問題'],[solved,'解き明かした問題'],[group.reduce((n,g)=>n+(g.questionCount||0),0),'質問の合計']]};}
