 if(id==='bestfive'){const rounds=group.flatMap(g=>g.rounds||[]),solved=rounds.filter(r=>r.reason==='solved').length;return {summary:done.length+'回 · 完全一致'+solved+'回'+tail,items:[[done.length,'遊び終えた回数'],[rounds.length,'答え合わせしたランキング'],[solved,'完全一致'],[rounds.reduce((n,r)=>n+(r.questions?.length||0),0),'質問の合計']]};}
