function recordRow(g){return `<article class="record">${recordGameIcon(g)}<div class="record-info"><strong>${gameName(g)}${g.playStyle==='quick'?(['liars','paraphrase','indian','bestfive','wordscale'].includes(g.game)?' · お試し版':' · お気軽版'):''} ／ ${esc(g.personaName)}</strong><small>${date(g.createdAt)} · ${g.version}${g.game!=='reversi'?'操作':'手'}${g.mode==='practice'?' · 練習':''}${g.game==='hitblow'?' · 答え同色'+(g.rulesConfig.allowDuplicates?'あり':'なし'):''}${g.game==='lastcard'?' · '+g.rulesConfig.playerCount+'人戦 · ドロー重ね'+(g.rulesConfig.stacking?'あり':'なし')+' · まとめ出し'+(g.rulesConfig.multiPlay?'あり':'なし'):''}${g.game==='blackjack'&&g.splitEnabled?' · スプリットあり':''}${g.game==='lateral'?' · '+(g.source==='private'?'私用の創作問題':g.puzzle?.number?'問題 No.'+String(g.puzzle.number).padStart(3,'0'):'練習問題')+' · '+g.questionCount+'質問':''}${g.game==='bestfive'?' · '+g.rounds.length+'/'+g.roundLimit+'ラウンド':g.game==='wordscale'?' · '+g.clearedStages+'/'+g.stageLimit+'ステージクリア':''}${g.game==='mancala'?' · '+(g.rulesConfig.winCondition==='empty'?'小皿を先に空にする':'集めた石の数で勝負'):''}</small></div><span class="result-pill">${(g.game==='paraphrase'&&g.status==='finished'?'完了':null)||(g.game==='bestfive'&&g.status==='finished'?'振り返り':null)||(g.game==='lateral'?(g.result==='clear'?'解明':g.result==='failed'?'答えを公開':null):null)||resultNames[g.result]||(g.status==='playing'?'進行中':'中止')}${g.game==='hitblow'&&g.matchDecided&&g.status==='playing'?' · 挑戦続行中':''}</span><a class="secondary" href="#game/${g.id}">${g.status==='playing'?'再開':'見る'} ↗</a></article>`;}
